def findKDistantIndices(nums, key, k):
    n = len(nums)
    marked = set()
    for j, val in enumerate(nums):
        if val == key:
            # Mark indices from max(0, j - k) to min(n - 1, j + k)
            left = max(0, j - k)
            right = min(n - 1, j + k)
            for i in range(left, right + 1):
                marked.add(i)
    return sorted(marked)
